#include <vector>
#include <algorithm>
#include <cstddef>
#include <omp.h>

double sumOfMinimumElements(std::vector<double> const& x, std::vector<double> const& y) {
    const std::size_t n = std::min(x.size(), y.size());
    double sum = 0.0;

    #pragma omp parallel for reduction(+:sum)
    for (std::size_t i = 0; i < n; ++i) {
        sum += std::min(x[i], y[i]);
    }

    return sum;
}
